/* @lc app=leetcode id=3283 lang=kotlin */ class Solution { fun bfs(sx: Int, sy: Int): IntArray = IntArray(2500) { -1 }.also { it[sx * 50 + sy] = 0 }.also { d -> generateSequence(listOf(sx * 50 + sy)) { f -> f.flatMap { u -> listOf(1 to 2, 2 to 1, -1 to 2, -2 to 1, 1 to -2, 2 to -1, -1 to -2, -2 to -1).map { (dx, dy) -> u / 50 + dx to u % 50 + dy }.filter { (x, y) -> x in 0..49 && y in 0..49 }.map { (x, y) -> x * 50 + y }.filter { d[it] == -1 }.distinct().onEach { v -> d[v] = d[u] + 1 } }.takeIf { it.isNotEmpty() } }.count() } fun g(mask: Int, last: Int, n: Int, dist: List<IntArray>, pts: List<Int>, m: HashMap<Int, Int>): Int = if (mask == (1 shl n) - 1) 0 else m.getOrPut(mask * 16 + last) { (0 until n).filter { mask shr it and 1 == 0 }.map { j -> dist[last][pts[j]] + g(mask or (1 shl j), j, n, dist, pts, m) }.let { if (Integer.bitCount(mask) % 2 == 0) it.max() else it.min() } } fun maxMoves(kx: Int, ky: Int, positions: Array<IntArray>): Int = (positions.toList() + listOf(intArrayOf(kx, ky))).map { bfs(it[0], it[1]) }.let { dist -> g(0, positions.size, positions.size, dist, positions.map { it[0] * 50 + it[1] }, HashMap()) } }